## 3️⃣ mobile – React Native (Expo)

### `mobile/package.json`

```json
{
 "name": "shop-match-mobile",
 "version": "1.0.0",
 "main": "node_modules/expo/AppEntry.js",
 "scripts": {
 "start": "expo start",
 "android": "expo run:android",
 "ios": "expo run:ios"
 },
 "dependencies": {
 "expo": "~50.0.0",
 "react": "18.3.0",
 "react-native": "0.74.1",
 "axios": "^1.7.2",
 "react-navigation": "^6.1.8",
 "@react-navigation/native": "^6.1.9",
 "@react-navigation/native-stack": "^6.9.19"
 }
}
```

### `mobile/src/api.js`

```js
import axios from "axios";

const API_URL = "http://YOUR_BACKEND_IP:5000/api";

export const fetchShops = async () => {
 const res = await axios.get(`${API_URL}/shops`);
 return res.data;
};

export const fetchRecommendations = async (userId) => {
 const res = await axios.get(`${API_URL}/match/${userId}`);
 return res.data;
};

export const createUser = async (payload) => {
 const res = await axios.post(`${API_URL}/users`, payload);
 return res.data;
};
```

### מסך הבית (`HomeScreen.js`)

```jsx
import React, { useEffect, useState } from "react";
import { View, Text, FlatList, TouchableOpacity, ActivityIndicator } from "react-native";
import { fetchRecommendations } from "../api";

export default function HomeScreen({ navigation, route }) {
 const [shops, setShops] = useState([]);
 const [loading, setLoading] = useState(true);
 const userId = route.params?.userId; // נניח שה‑userId נשלח אחרי רישום

 useEffect(() => {
 (async () => {
 try {
 const data = await fetchRecommendations(userId);
 setShops(data);
 } catch (e) {
 console.warn(e);
 } finally {
 setLoading(false);
 }
 })();
 }, [userId]);

 if (loading) return <ActivityIndicator size="large" style={{ marginTop: 50 }} />;

 return (
 <View style={{ flex: 1, padding: 16 }}>
 <Text style={{ fontSize: 22, marginBottom: 12 }}>ההמלצות שלך</Text>
 <FlatList
 data={shops}
 keyExtractor={item => item._id}
 renderItem={({ item }) => (
 <TouchableOpacity
 style={{
 padding: 12,
 borderBottomWidth: 1,
 borderColor: "#ddd"
 }}
 onPress={() => navigation.navigate("ShopDetail", { shopId: item._id })}
 >
 <Text style={{ fontSize: 18 }}>{item.name}</Text>
 <Text style={{ color: "#666" }}>{item.category}</Text>
 </TouchableOpacity>
 )}
 />
 </View>
 );
}
```

